-- Migration: Year 4 - Ethics, Law & Health Systems (PART 5: 201-250)
-- Date: 2026-05-16
-- Target: US MD / MBBS / USMLE Step 3 Level
-- Topic: Healthcare systems — ACA, HIPAA, & Regulatory Laws

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    -- Fetch the topic_id dynamically via slug
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-healthcare-systems' LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic with slug "ethics-healthcare-systems" not found.';
    END IF;

    -- SECTION: AFFORDABLE CARE ACT (ACA) CORE PROVISIONS
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'The "Health Insurance Marketplaces" (Exchanges) created by the ACA are primarily for which group of people?', '["People with employer-sponsored insurance", "Individuals and small businesses who need to purchase their own health insurance", "Only undocumented immigrants", "Seniors on Medicare"]', 1, 'Marketplaces provide a centralized way to compare and buy individual health plans.'),
    (v_topic_id, 'Which of the following describes the "Premium Tax Credit" (Subsidy) available on the ACA marketplace?', '["A tax on people who buy expensive plans", "A federal subsidy to help low-to-moderate income individuals pay their monthly insurance premiums", "A refund for doctors", "None of the above"]', 1, 'Subsidies are available to those with incomes between 100% and 400% of the FPL (expanded temporarily by the IRA).'),
    (v_topic_id, 'Under the ACA, "Cost-Sharing Reductions" (CSRs) are additional subsidies that help lower which of the following costs for eligible individuals?', '["Monthly premiums", "Deductibles, copayments, and coinsurance", "Hospital parking fees", "Income taxes"]', 1, 'CSRs are only available for those who purchase "Silver" level plans and have incomes up to 250% FPL.'),
    (v_topic_id, 'The ACA "Individual Mandate" originally required most Americans to have health insurance or pay a tax penalty. What is the current status of the federal individual mandate penalty?', '["It has been increased", "It was reduced to $0 starting in 2019", "It only applies to people over 50", "It was declared unconstitutional and removed"]', 1, 'While the mandate remains law, the penalty was effectively zeroed out by the Tax Cuts and Jobs Act of 2017.'),
    (v_topic_id, 'Which ACA provision allows young adults to remain on their parents'' health insurance plans?', '["Until they graduate college", "Until they turn 26", "Until they turn 30", "Only if they are full-time students"]', 1, 'The "under 26" rule applies regardless of whether the child is a student, lives at home, or is married.'),
    (v_topic_id, 'The "Employer Mandate" (Employer Shared Responsibility Payment) applies to businesses with at least how many full-time equivalent employees?', '["10", "25", "50", "100"]', 2, 'Employers with 50+ employees must offer affordable, minimum-value coverage to their full-time staff.'),
    (v_topic_id, 'Which of the following is NOT one of the 10 "Essential Health Benefits" (EHBs) that most ACA-compliant plans must cover?', '["Maternity and newborn care", "Mental health and substance use disorder services", "Adult vision and dental care", "Pediatric services (including dental and vision)"]', 2, 'Routine adult vision and dental are NOT mandatory EHBs, although pediatric vision and dental ARE.'),
    (v_topic_id, 'The ACA prohibited insurance companies from placing which of the following on essential health benefits?', '["Annual limits only", "Lifetime dollar limits only", "Both annual and lifetime dollar limits", "Any limit on the number of doctor visits"]', 2, 'Insurers can no longer cap the total amount they will pay for a person''s care over their lifetime or in a single year for EHBs.'),

    -- SECTION: HIPAA (HEALTH INSURANCE PORTABILITY AND ACCOUNTABILITY ACT)
    (v_topic_id, 'The "Privacy Rule" of HIPAA applies to "Covered Entities." Which of the following is a covered entity?', '["Healthcare providers (doctors, hospitals)", "Health plans (insurers)", "Healthcare clearinghouses", "All of the above"]', 3, 'Covered entities are those that transmit health information electronically in connection with certain transactions.'),
    (v_topic_id, 'Under HIPAA, "Protected Health Information" (PHI) includes which of the following?', '["Name and address", "Social security number", "Medical record numbers and photos", "All of the above"]', 3, 'PHI includes any information that can reasonably be used to identify a patient and relates to their health or payment for care.'),
    (v_topic_id, 'Does HIPAA allow a physician to share PHI with another provider for the purpose of "Treatment, Payment, or Healthcare Operations" (TPO) without specific patient authorization?', '["No, never", "Yes, authorization is generally not required for TPO purposes", "Only if the patient is unconscious", "Only if the patient is a minor"]', 1, 'TPO is a broad exception that allows the healthcare system to function efficiently.'),
    (v_topic_id, 'Under the HIPAA "Security Rule," what is "ePHI"?', '["Emergency Patient Health Information", "Electronic Protected Health Information", "Essential Private Health Information", "None of the above"]', 1, 'The Security Rule focuses specifically on the technical and administrative safeguards for electronic data.'),
    (v_topic_id, 'Which federal agency is responsible for enforcing HIPAA privacy and security rules?', '["The FBI", "The Office for Civil Rights (OCR) within HHS", "The CMS", "The FDA"]', 1, 'OCR investigates breaches and issues fines for HIPAA violations.'),
    (v_topic_id, 'What is a "Business Associate" under HIPAA?', '["A fellow doctor", "A person or entity that performs functions on behalf of a covered entity that involve the use of PHI (e.g., a billing company or IT provider)", "A pharmaceutical salesperson", "The hospital chaplain"]', 1, 'Business associates must sign agreements promising to protect PHI.'),
    (v_topic_id, 'The "Minimum Necessary" standard in HIPAA means that:', '["Doctors should spend the minimum time possible with patients", "Covered entities must make reasonable efforts to use or disclose only the amount of PHI needed to accomplish the intended purpose", "Patients should only be told the minimum about their diagnosis", "Hospitals should have the minimum number of staff"]', 1, 'Employees should only access the data they need to do their specific job.'),

    -- SECTION: ERISA & GINA
    (v_topic_id, 'ERISA (Employee Retirement Income Security Act) primarily regulates:', '["Medicare eligibility", "Employer-sponsored pension and welfare (health) benefit plans", "Medical malpractice lawsuits", "The price of prescription drugs"]', 1, 'ERISA ensures that employees receive the benefits promised by their private-sector employers.'),
    (v_topic_id, 'The "GINA" (Genetic Information Nondiscrimination Act) prohibits health insurers from using genetic information to:', '["Determine eligibility or premiums", "Inform a patient of a disease risk", "Coordinate care for a known genetic condition", "Pay for genetic testing"]', 0, 'GINA protects individuals from being discriminated against based on their genetic predisposition to a disease.'),
    (v_topic_id, 'Does GINA apply to life insurance, disability insurance, or long-term care insurance?', '["Yes, all insurance", "No, it primarily applies to health insurance and employment", "Only if the person is under 21", "Only for cancer-related genes"]', 1, 'GINA''s protections are notably absent from life, disability, and long-term care insurance markets.'),

    -- SECTION: MENTAL HEALTH PARITY
    (v_topic_id, 'The Mental Health Parity and Addiction Equity Act (MHPAEA) requires that:', '["All health plans must cover mental health", "If a plan covers mental health, the financial requirements (e.g., copays) and treatment limits cannot be more restrictive than those for medical/surgical benefits", "Mental health care must be free", "Only psychiatrists can treat depression"]', 1, 'Parity means mental health should be treated the same as physical health in terms of insurance coverage rules.'),
    (v_topic_id, 'Which of the following is an example of a "Non-Quantitative Treatment Limit" (NQTL) in mental health parity?', '["A $40 copay", "A 10-visit limit", "Prior authorization requirements or network adequacy standards", "The annual deductible"]', 2, 'NQTLs are administrative barriers that must also be applied equitably under parity laws.'),

    -- SECTION: HITECH & ELECTRONIC RECORDS
    (v_topic_id, 'The HITECH Act was part of the 2009 Stimulus Bill. Its primary goal was to:', '["Lower the cost of computers", "Promote the adoption and "Meaningful Use" of electronic health records (EHRs)", "Hire more IT professionals", "Create a government-run health record for all citizens"]', 1, 'HITECH provided financial incentives for providers to move from paper to electronic systems.'),
    (v_topic_id, 'Under the HITECH Act, if a "Breach" of unsecured PHI affects more than how many individuals, the covered entity must notify the media and the HHS immediately?', '["10", "100", "500", "1,000"]', 2, 'Breaches involving 500+ people are often referred to as "Wall of Shame" incidents.'),

    -- SECTION: OTHER FEDERAL LAWS
    (v_topic_id, 'The "Newborns'' and Mothers'' Health Protection Act" mandates that health plans cover a hospital stay of at least how many hours following a normal vaginal delivery?', '["12 hours", "24 hours", "48 hours", "96 hours"]', 2, 'The law mandates 48 hours for vaginal delivery and 96 hours for a Cesarean section.'),
    (v_topic_id, 'The "Women''s Health and Cancer Rights Act" (WHCRA) requires plans that cover mastectomies to also cover:', '["Breast reconstruction and prostheses", "Chemotherapy only", "Wigs", "None of the above"]', 0, 'WHCRA ensures that patients have access to reconstructive surgery following a mastectomy.'),
    (v_topic_id, 'Which of the following laws was passed to ensure that patients have access to their own medical records and to promote the sharing of health information (prevent "Information Blocking")?', '["The Patriot Act", "The 21st Century Cures Act", "The Medicare Modernization Act", "The Pure Food and Drug Act"]', 1, 'The Cures Act emphasizes patient access to their own electronic health information.'),

    -- SECTION: ACA MARKETPLACE DETAILS
    (v_topic_id, 'In the ACA marketplace, a "Bronze" plan typically has:', '["The highest premiums and lowest deductibles", "The lowest premiums and highest out-of-pocket costs", "No deductible", "Coverage only for primary care"]', 1, 'Bronze plans are designed to cover 60% of average medical costs, leaving 40% to the patient.'),
    (v_topic_id, 'A "Silver" plan on the marketplace is significant because:', '["It is the only plan that covers cancer", "It is the benchmark plan used to calculate premium tax credits and is the only plan type eligible for Cost-Sharing Reductions (CSRs)", "It has the lowest cost of all plans", "It is for seniors only"]', 1, 'Silver plans are the most common choice for subsidized individuals.'),
    (v_topic_id, 'A "Gold" or "Platinum" plan on the marketplace is best for someone who:', '["Wants to pay the lowest monthly premium possible", "Has high healthcare utilization and wants lower out-of-pocket costs at the time of service", "Is perfectly healthy", "Only wants emergency coverage"]', 1, 'Higher-tier plans have higher premiums but much lower deductibles and coinsurance.'),
    (v_topic_id, '"Catastrophic" plans on the ACA marketplace are generally only available to people who:', '["Are over 65", "Are under 30 or have a "hardship exemption"", "Have a terminal illness", "Have already met their deductible"]', 1, 'Catastrophic plans have very low premiums but very high deductibles and are restricted to young adults or those with extreme financial hardship.'),

    -- SECTION: MORE HIPAA & PRIVACY
    (v_topic_id, 'Can a hospital disclose PHI to a patient''s "family, friends, or others involved in the patient''s care"?', '["No, never without a written contract", "Yes, if the patient is present and does not object, or if the provider uses professional judgment that it is in the patient''s best interest", "Only if the person has a power of attorney", "Only if the patient is dying"]', 1, 'HIPAA allows for common-sense communication with those involved in a patient''s care unless the patient explicitly opts out.'),
    (v_topic_id, 'Does HIPAA allow the use of PHI for "Marketing" purposes without patient authorization?', '["Yes", "No, specific written authorization is generally required for marketing communications", "Only if the doctor is selling the product", "Only if the product is a drug"]', 1, 'Marketing is strictly regulated under HIPAA.'),
    (v_topic_id, 'A patient asks to amend an error in their medical record. Under HIPAA, the provider:', '["Must delete the error immediately", "Must act on the request (either amend it or provide a reason for denial) within 60 days", "Can ignore the request", "Must give the patient a refund"]', 1, 'Patients have the right to request amendments to their PHI.'),

    -- SECTION: ACA REGULATORY DETAILS
    (v_topic_id, 'What is "Risk Adjustment" in the ACA marketplace?', '["A way to charge sick people more", "A program that redistributes funds from plans with healthier-than-average enrollees to plans with sicker-than-average enrollees", "A way to measure hospital safety", "None of the above"]', 1, 'Risk adjustment prevents "creaming" (only taking healthy patients) by making it financially viable to cover sick patients.'),
    (v_topic_id, 'What is the "Navigators" program in the ACA?', '["A group of pilots who fly patients to hospitals", "Trained individuals and organizations that help consumers look for, compare, and enroll in marketplace health plans", "A type of GPS for ambulances", "None of the above"]', 1, 'Navigators provide free, impartial assistance to consumers.'),
    (v_topic_id, 'Are ACA marketplace plans allowed to have "Waiting Periods" for pre-existing conditions?', '["Yes, up to 12 months", "No, coverage must be effective immediately with no exclusions for pre-existing conditions", "Only for employer plans", "Only for dental care"]', 1, 'The elimination of pre-existing condition exclusions is a fundamental tenet of the ACA.'),

    -- SECTION: MISCELLANEOUS REGULATORY
    (v_topic_id, 'The "Sunshine Act" (Physician Payments Sunshine Act) requires:', '["Hospitals to have more windows", "Manufacturers of drugs and devices to publicly report payments or "transfers of value" (e.g., meals, consulting fees) made to physicians and teaching hospitals", "Doctors to work during daylight hours", "Insurance companies to be transparent about their profits"]', 1, 'The Sunshine Act promotes transparency in the relationships between industry and clinicians.'),
    (v_topic_id, 'The "Federal Trade Commission" (FTC) often investigates which of the following in healthcare?', '["Medical malpractice", "Hospital mergers and anti-competitive behavior", "Medicare billing fraud", "The safety of new drugs"]', 1, 'The FTC ensures that hospital and provider consolidations do not lead to monopolies and higher prices.'),
    (v_topic_id, 'What is "Deemed Status" in hospital regulation?', '["A hospital that is considered dead", "When a hospital is "deemed" to meet Medicare requirements because it is accredited by an approved organization like The Joint Commission", "A hospital that only sees children", "None of the above"]', 1, 'Accreditation by The Joint Commission is a common way for hospitals to maintain Medicare participation.'),
    (v_topic_id, 'The "National Practitioner Data Bank" (NPDB) is a database that contains:', '["The names of all patients in the US", "Information on medical malpractice payments and adverse actions (e.g., license revocations) taken against healthcare practitioners", "A list of all hospitals", "A list of all medical schools"]', 1, 'The NPDB is used by hospitals and licensing boards during the credentialing process.'),
    (v_topic_id, 'The "Tax Cuts and Jobs Act of 2017" had what major impact on the ACA?', '["It doubled the subsidies", "It reduced the individual mandate penalty to $0", "It expanded Medicaid in all states", "It abolished the marketplaces"]', 1, 'By zeroing the penalty, it effectively removed the enforcement of the individual mandate.'),
    (v_topic_id, 'Which of the following is true about "Grandfathered" health plans under the ACA?', '["They must follow all new ACA rules", "They are plans that existed before the ACA and are exempt from some new requirements (like covering preventive care at $0) as long as they don''t make significant changes", "They are only for people over age 80", "They are illegal now"]', 1, 'Grandfathered plans are becoming increasingly rare as they evolve and lose their status.'),
    (v_topic_id, 'A "Small Group" health plan is typically for employers with how many employees?', '["1-10", "1-50 (or 1-100 in some states)", "50-100", "Only for 1 person"]', 1, 'The ACA established specific rules and protections for the small group market.'),
    (v_topic_id, 'Which organization is responsible for developing the "Healthy People" national health objectives every 10 years?', '["The WHO", "The US Department of Health and Human Services (HHS)", "The American Medical Association", "The Red Cross"]', 1, 'Healthy People provides data-driven benchmarks for the nation''s health.'),
    (v_topic_id, 'What is the "Notice of Privacy Practices" (NPP) in HIPAA?', '["A secret document for doctors", "A document that explains to patients how their PHI may be used and disclosed and their rights regarding that information", "A bill for medical records", "None of the above"]', 1, 'Providers must give the NPP to patients at their first visit.'),
    (v_topic_id, 'Can a patient "Opt-Out" of the hospital directory under HIPAA?', '["No", "Yes, they can choose to not have their name and location listed in the directory that is shared with the public", "Only if they are famous", "Only if they pay extra"]', 1, 'Patients have the right to remain "incognito" in the hospital.'),
    (v_topic_id, 'Is it a HIPAA violation for a doctor to discuss a patient''s case in a crowded elevator where other people can hear?', '["No, if they don''t use the patient''s name", "Yes, it is a failure to maintain reasonable safeguards to protect privacy", "Only if the elevator is in a different building", "None of the above"]', 1, 'Professional discussions should take place in private areas to avoid "incidental" disclosures to unauthorized ears.'),
    (v_topic_id, 'Which of the following is a "Physical Safeguard" under the HIPAA Security Rule?', '["A password", "Locking the room where the server is located", "Encryption of data", "Training staff on phishing"]', 1, 'Physical safeguards involve the actual security of the facilities and equipment.'),
    (v_topic_id, 'Which of the following is a "Technical Safeguard" under the HIPAA Security Rule?', '["A security guard", "An audit trail to see who accessed which electronic records", "A locked filing cabinet", "A background check on employees"]', 1, 'Technical safeguards involve the technology used to protect and control access to ePHI.'),
    (v_topic_id, 'The "No Surprises Act" (2022) protects patients from out-of-network bills in which of the following scenarios?', '["Emergency services", "Air ambulance services", "Non-emergency services at an in-network facility when the provider is out-of-network", "All of the above"]', 3, 'The Act was a major bipartisan step in protecting patients from unexpected medical debt.'),
    (v_topic_id, 'Under the No Surprises Act, if there is a payment dispute between an insurer and an out-of-network provider, how is it settled?', '["The patient pays the difference", "An Independent Dispute Resolution (IDR) process (arbitration)", "The government pays", "The provider must accept whatever is offered"]', 1, 'The IDR process takes the patient "out of the middle" of the dispute.')
;

END $$;
COMMIT;
